(()=>{'use strict';const root=document.documentElement;root.dataset.ssPage=location.pathname.endsWith('/training.html')?'training':'learn';let warned=false;function warning(){if(warned)return;warned=true;const show=()=>{const n=document.createElement('div');n.className='ss-warning';n.setAttribute('role','status');n.textContent='無法儲存本機紀錄，請先匯出備份並檢查瀏覽器設定。';document.body.prepend(n)};document.body?show():document.addEventListener('DOMContentLoaded',show,{once:true})}window.SSStorage={get(k){try{return localStorage.getItem(k)}catch{warning();return null}},set(k,v){try{localStorage.setItem(k,v);return true}catch{warning();return false}},remove(k){try{localStorage.removeItem(k);return true}catch{warning();return false}}};function vp(){const v=window.visualViewport;root.style.setProperty('--ss-vh',(v?v.height:innerHeight)+'px');root.style.setProperty('--ss-top',(v?v.offsetTop:0)+'px');root.classList.toggle('ss-keyboard',!!v&&innerHeight-v.height>140)}vp();addEventListener('resize',vp);if(window.visualViewport){visualViewport.addEventListener('resize',vp);visualViewport.addEventListener('scroll',vp)}let active=null,prior=null;const visible=e=>e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden';const focusables=m=>[...m.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled):not([type=hidden]),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(visible);
function sync(){const next=[...document.querySelectorAll('.modal,.first-run-flow')].filter(visible).sort((a,b)=>(parseInt(getComputedStyle(a).zIndex)||0)-(parseInt(getComputedStyle(b).zIndex)||0)).pop()||null;if(next!==active){if(next){if(!active)prior=document.activeElement;active=next;next.tabIndex=-1;requestAnimationFrame(()=>{if(active===next&&!next.contains(document.activeElement))(focusables(next)[0]||next).focus({preventScroll:true})})}else{active=null;if(prior?.isConnected)prior.focus({preventScroll:true});prior=null}}const tab=document.body.dataset.activeTab||'plan';document.querySelectorAll('#app-bottom-nav [data-app-tab]').forEach(e=>{if(e.dataset.appTab===tab){if(e.getAttribute('aria-current')!=='page')e.setAttribute('aria-current','page')}else if(e.hasAttribute('aria-current'))e.removeAttribute('aria-current')});}
function grids(){document.querySelectorAll('.rg,.chart-grid,.range-editor-grid').forEach(g=>{if(g.closest('.ss-grid-wrap'))return;const w=document.createElement('div'),sc=document.createElement('div'),b=document.createElement('button');w.className='ss-grid-wrap';sc.className='ss-grid-scroll';sc.tabIndex=0;sc.setAttribute('role','region');sc.setAttribute('aria-label','範圍矩陣，可左右捲動');b.className='ss-link';b.textContent='放大矩陣／觸控模式';b.type='button';b.setAttribute('aria-expanded','false');g.before(w);w.append(b,sc);sc.append(g);b.onclick=()=>{const on=w.classList.toggle('ss-grid-expanded');b.setAttribute('aria-expanded',String(on));b.textContent=on?'還原矩陣':'放大矩陣／觸控模式'}})}document.addEventListener('DOMContentLoaded',()=>{grids();sync();new MutationObserver(()=>{grids();sync()}).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class','style','data-active-tab']})});document.addEventListener('keydown',e=>{if(!active)return;const f=focusables(active);if(e.key==='Tab'){if(!f.length){e.preventDefault();active.focus()}else if(e.shiftKey&&(!active.contains(document.activeElement)||document.activeElement===f[0])){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&(!active.contains(document.activeElement)||document.activeElement===f.at(-1))){e.preventDefault();f[0].focus()}}else if(e.key==='Escape'&&active.id!=='confirm-modal'){const b=active.querySelector('.btn-close');if(b){e.preventDefault();e.stopImmediatePropagation();b.click()}}},true);document.addEventListener('focusin',e=>{if(active&&!active.contains(e.target))(focusables(active)[0]||active).focus({preventScroll:true})})})();